export default function Product(props) {
  function addToCart() {
    var productCode = props.code;
    var productName = props.name;

  }
  return (
    <span className={`product_container product_${props.id}`}>
      <h2>{props.name}</h2>
      {props.img_src && <img src={props.img_src} alt={props.name} className="product_image" width={props.dimensions.width} height={props.dimensions.height} />}
      <p>Price: ₹{props.price}</p>
      <p>{props.description}</p>
      <span className="product_actions">
        <button className="addToCartButton" onClick={addToCart}>Add to Cart</button>
        {props.count !== undefined && <p>count : {props.count}</p>}
      </span>
    </span>
  );
}
